using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class EpkCabProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}
static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var loc=mem["TLocParam"];int vcu=int.Parse(args[0]),trip=int.Parse(args[1]),kvt=int.Parse(args[2]);Marshal.WriteByte(loc,0x8f,(byte)vcu);Marshal.WriteByte(loc,0x7e,(byte)kvt);Marshal.WriteByte(loc,0x9b,(byte)trip);var cars=(IntPtr[])typeof(TrainerIntegrationHost).GetField("cars",flags).GetValue(h);for(int n=0;n<600;n++){Call(h,"PneumaticCycle");foreach(var c in cars){float p=F(c,0);if(float.IsNaN(p)||float.IsInfinity(p)||p<0)throw new Exception("Invalid TM");}}float tm=F(cars[0],0),tc=F(loc,13);Marshal.WriteByte(loc,0x9b,0);Marshal.WriteByte(loc,0x8f,1);Marshal.WriteByte(loc,0x7d,2);Marshal.WriteByte(loc,0x7e,2);for(int n=0;n<1800;n++)Call(h,"PneumaticCycle");float recovered=F(cars[0],0);if(trip==1&&recovered<4.8)throw new Exception("TM recovery failed");var result=new{vcu=vcu,trip=trip,kvt=kvt,tm_after_60s=tm,tc_after_60s=tc,tm_after_reset_180s=recovered,scope="Forced EPK trip; pressure state, not KLUB trip generation or physical cock model"};string json=new JavaScriptSerializer().Serialize(result);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"EPK_cab_baseline_"+string.Join("_",args)+".json"),json);Console.WriteLine(json);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{h.Close();h.Dispose();}}
}

